// ==========================================
// REAL ORDER SUBMISSION (GAS + YCF 152-FZ)
// ==========================================
async function sendStoreOrder(orderData) {
  const orderId = 'TM-' + Math.floor(1000 + Math.random() * 9000);
  orderData.order_id = orderId;
  orderData.source = window.location.href;
  orderData.timestamp = new Date().toISOString();

  // 1. Google Apps Script POST
  try {
    fetch(LEAD_ENDPOINT, {
      method: 'POST',
      mode: 'no-cors',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        ...orderData,
        type: orderData.type || 'store_order'
      })
    }).catch(err => console.warn('GAS dispatch error:', err));
  } catch (e) {
    console.warn('GAS network issue:', e);
  }

  // 2. Yandex Cloud Function POST (152-FZ + Telegram bot)
  try {
    const tgMessage = `Заказ #${orderId}\nКлиент: ${orderData.name}\nТелефон: ${orderData.phone}\nГород: ${orderData.city}\nОплата: ${orderData.payment}\nСумма: ${orderData.total_sum.toLocaleString('ru-RU')} ₽\n\nТовары:\n${orderData.items_summary}`;

    fetch(YANDEX_152FZ_ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: orderData.name,
        company: `TIMETRY STORE (${orderId})`,
        role: orderData.city,
        contact_type: 'Телефон',
        contact: orderData.phone,
        wishes: tgMessage,
        source: window.location.href,
        order_id: orderId,
        type: orderData.type || 'store_order'
      })
    }).catch(err => console.warn('YCF dispatch error:', err));
  } catch (e) {
    console.warn('YCF network issue:', e);
  }

  // Show Success Modal (if not callback)
  if (orderData.type !== 'callback') {
    const successIdEl = document.getElementById('success-order-id');
    if (successIdEl) successIdEl.textContent = orderId;
    openModal('order-success-modal');
  }

  return orderId;
}

