function closeModal(id) {
  const modal = document.getElementById(id);
  if (modal) modal.classList.remove('active');
}

function showToast(msg) {
  let container = document.getElementById('toast-container');
  if (!container) {
    container = document.createElement('div');
    container.id = 'toast-container';
    container.className = 'toast-container';
    document.body.appendChild(container);
  }

  const toast = document.createElement('div');
  toast.className = 'toast';
  toast.innerHTML = `<span>${msg}</span>`;
  container.appendChild(toast);

  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateY(10px)';
    setTimeout(() => toast.remove(), 250);
  }, 3000);
}

// ==========================================
// EVENT LISTENERS WIRING
// ==========================================
function initEventListeners() {
  // Category pills
  document.querySelectorAll('.cat-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      resetCatalogPagination();
      document.querySelectorAll('.cat-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      AppState.activeFilters.category = btn.dataset.cat;
      applyFilters();
    });
  });

  // Filter tags in sidebar (using event delegation to support both static and dynamically discovered tags)
  const sidebarEl = document.querySelector('.store-sidebar');
  if (sidebarEl) {
    sidebarEl.addEventListener('click', (e) => {
      const pill = e.target.closest('.filter-tag-btn');
      if (!pill) return;

      resetCatalogPagination();
      const type = pill.dataset.filterType;
      const val = pill.dataset.filterVal;
      const groupPills = pill.parentElement.querySelectorAll('.filter-tag-btn');

      if (pill.classList.contains('active')) {
        if (type === 'brand' && val === 'all') return;
        pill.classList.remove('active');
        AppState.activeFilters[type] = 'all';
        if (type === 'brand') {
          const allBtn = pill.parentElement.querySelector('[data-filter-val="all"]');
          if (allBtn) allBtn.classList.add('active');
        }
      } else {
        groupPills.forEach(p => p.classList.remove('active'));
        pill.classList.add('active');
        AppState.activeFilters[type] = val;
      }
      applyFilters();
    });
  }

  // Model search input in sidebar
  const modelInput = document.getElementById('model-filter-input');
  const modelClear = document.getElementById('model-filter-clear');
  if (modelInput) {
    let timeout = null;
    modelInput.addEventListener('input', (e) => {
      clearTimeout(timeout);
      const val = e.target.value;
      if (modelClear) modelClear.style.display = val ? 'block' : 'none';
      timeout = setTimeout(() => {
        resetCatalogPagination();
        AppState.activeFilters.modelQuery = val;
        applyFilters();
      }, 150);
    });
  }
  if (modelClear) {
    modelClear.addEventListener('click', () => {
      if (modelInput) {
        modelInput.value = '';
        modelInput.focus();
      }
      modelClear.style.display = 'none';
      resetCatalogPagination();
      AppState.activeFilters.modelQuery = '';
      applyFilters();
    });
  }

  // Model quick select dropdown
  const modelSelect = document.getElementById('model-quick-select');
  if (modelSelect) {
    modelSelect.addEventListener('change', (e) => {
      resetCatalogPagination();
      AppState.activeFilters.specificModel = e.target.value;
      applyFilters();
    });
  }

  // Search input
  const searchInput = document.getElementById('catalog-search-input');
  if (searchInput) {
    let timeout = null;
    searchInput.addEventListener('input', (e) => {
      clearTimeout(timeout);
      timeout = setTimeout(() => {
        resetCatalogPagination();
        AppState.activeFilters.search = e.target.value;
        applyFilters();
      }, 200);
    });
  }

  // Sort select
  const sortSelect = document.getElementById('catalog-sort-select');
  if (sortSelect) {
    sortSelect.addEventListener('change', (e) => {
      resetCatalogPagination();
      AppState.activeFilters.sort = e.target.value;
      applyFilters();
    });
  }

  // Price inputs
  const minPriceInput = document.getElementById('min-price-input');
  const maxPriceInput = document.getElementById('max-price-input');
  if (minPriceInput) {
    minPriceInput.addEventListener('input', (e) => {
      resetCatalogPagination();
      AppState.activeFilters.minPrice = Number(e.target.value) || 0;
      applyFilters();
    });
  }
  if (maxPriceInput) {
    maxPriceInput.addEventListener('input', (e) => {
      resetCatalogPagination();
      AppState.activeFilters.maxPrice = Number(e.target.value) || 500000;
      applyFilters();
    });
  }

  // Close modals on backdrop click
  document.querySelectorAll('.modal-overlay').forEach(modal => {
    modal.addEventListener('click', (e) => {
      if (e.target === modal) {
        modal.classList.remove('active');
      }
    });
  });

  // Keyboard navigation & modal closing
  document.addEventListener('keydown', (e) => {
    if (isLightboxOpen()) {
      if (e.key === 'ArrowRight') {
        nextLightboxImage();
      } else if (e.key === 'ArrowLeft') {
        prevLightboxImage();
      } else if (e.key === 'Escape') {
        closeLightbox();
      }
      return;
    }

    if (e.key === 'Escape') {
      document.querySelectorAll('.modal-overlay.active').forEach(m => m.classList.remove('active'));
      const drawer = document.getElementById('cart-drawer');
      if (drawer && drawer.classList.contains('open')) {
        drawer.classList.remove('open');
      }
    }
  });
}
